(2, 2, 'Комбиниране на документи', '{\"htmls\":[{\"name\":\"personal_page.html\",\"type\":\"text/text/html\",\"html\":\"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Джон Петров</title>\\n</head>\\n<body>\\n    <h1>Джон Петров</h1>\\n\\n    <p>Кратка информация за мен: студент 4-ти курс компютърни науки.</p>\\n\\n    <p>Любимите ми занимания:</p>\\n    <ul>\\n        <li>Спане</li>\\n        <li>Учене</li>\\n        <li>Гледане на филми</li>\\n        <li>Разходки</li>\\n        <li>Покер (не съм пристрастен)</li>\\n    </ul>\\n\\n    <a href=\\\"https://learn.fmi.uni-sofia.bg/user/profile.php?id=25933\\\" target=\\\"blank\\\">Моят профил в Moodle.</a>\\n</body>\\n</html>\",\"error\":0,\"size\":771},{\"name\":\"demo.html\",\"type\":\"text/text/html\",\"html\":\"<!doctype html>\\n<html><head><meta charset=\\\"utf-8\\\"><title>Demo</title></head>\\n<body>\\n<h1>Заглавие на реферат</h1>\\n<p>Това е примерен <strong>параграф</strong> с текст на български език. Целта е да се види как работи страницирането по символи на ред и по височина на страницата.</p>\\n<h2>Секция 2</h2>\\n<p>Още един параграф. Добавяме и списък:</p>\\n<ul><li>Първа точка</li><li>Втора точка</li><li>Трета точка</li></ul>\\n<pre>\\nfunction hello(name) {\\n  console.log(\\\"Hello, \\\" + name);\\n}\\n</pre>\\n</body></html>\\n\",\"error\":0,\"size\":699}],\"settings\":{\"page\":{\"page_size\":\"a5\",\"orientation\":\"portrait\",\"page_width\":148,\"page_height\":210,\"margin\":18,\"font_size\":12,\"line_spacing\":1,\"words\":0,\"lines\":0},\"pagination\":{\"show_page_numbers\":1,\"no_number_on_first\":1,\"page_number_pos\":\"footer\",\"page_number_format\":\"123\",\"page_number_template\":\"стр. {page}/{total}\",\"line_numbers_mode\":\"none\",\"line_numbers_placement\":\"\"},\"sections\":{\"new_page_on_header\":0,\"header_page_break_levels\":[],\"new_page_on_file\":1,\"file_name_as_section\":1,\"wrap_lines\":\"yes\"}},\"meta\":{\"title\":\"Комбиниране на два документа\",\"author\":\"Джон\",\"course\":\"Версия 1.0\",\"citation_template\":\"\",\"metadata_placement\":\"start\",\"statistics_placement\":\"none\"},\"stats\":{\"pages\":2,\"lines\":39,\"words\":79,\"avg_lines\":\"19.50\"}}', '2026-01-27 20:04:37', '2026-01-28 18:34:12');
INSERT INTO `projects` (`id`, `user_id`, `name`, `payload`, `created_at`, `updated_at`) VALUES
(3, 2, 'Тестов проект', '{\"htmls\":[{\"name\":\"referat.html\",\"type\":\"text/text/html\",\"html\":\"<!doctype html>\\n\\n<html lang=\\\"bg\\\">\\n  <head>\\n    <meta charset=\\\"utf-8\\\" />\\n    <meta content=\\\"width=device-width, initial-scale=1.0\\\" name=\\\"viewport\\\" />\\n    <title>CoffeeScript</title>\\n    <link href=\\\"css/main.css\\\" rel=\\\"stylesheet\\\" />\\n  </head>\\n  <body>\\n    <header class=\\\"site-header\\\">\\n      <div class=\\\"site-header__inner\\\">\\n        <h1 class=\\\"site-title\\\">CoffeeScript</h1>\\n        <h2 class=\\\"sub-title\\\">Сергей Данкогло, 5MI8000027</h2>\\n      </div>\\n    </header>\\n\\n    <main class=\\\"page\\\">\\n      <article class=\\\"report\\\">\\n\\n        <!-- СЪДЪРЖАНИЕ -->\\n\\n        <section class=\\\"section\\\" id=\\\"toc\\\">\\n          <h2 class=\\\"section-title\\\">Съдържание</h2>\\n          <ol class=\\\"toc-list\\\">\\n            <li><a href=\\\"#introduction\\\">Кратко въведение в CoffeeScript</a></li>\\n            <li><a href=\\\"#translator\\\">Що е то Транслатор?</a></li>\\n            <li><a href=\\\"#history\\\">Историята и хронологията на CoffeeScript</a></li>\\n            <li><a href=\\\"#goals\\\">Целите на CoffeeScript</a></li>\\n            <li><a href=\\\"#syntax\\\">Основни синтактични конструкции</a></li>\\n            <li><a href=\\\"#differences\\\">Разлики и предимства спрямо JavaScript</a></li>\\n            <li><a href=\\\"#practical-examples\\\">Малък уеб-сървър на CoffeeScript</a></li>\\n            <li><a href=\\\"#applications\\\">Примери на съществуващи приложения</a></li>\\n            <li><a href=\\\"#the-sad-truth\\\">Тъжната истина за CoffeeScript</a></li>\\n            <li><a href=\\\"#citations\\\">Списък от източници</a></li>\\n          </ol>\\n        </section>\\n\\n        <!-- 1. ВЪВЕДЕНИЕ -->\\n        \\n        <section class=\\\"section\\\" id=\\\"introduction\\\">\\n          <h2 class=\\\"section-title\\\">1. Кратко въведение в CoffeeScript</h2>\\n          <p>\\n            CoffeeScript е лек език за програмиране, който се транспилира\\n            (компилира) в JavaScript [1]. Той е създаден с идеята да подобри\\n            четимостта и краткостта на кода, като премахва много от тромавите\\n            синтактични елементи на JavaScript, като същевременно запазва\\n            пълната му функционалност и съвместимост. Основната философия е:\\n            <q>Това е просто JavaScript</q> [2].\\n          </p>\\n          <p>\\n            CoffeeScript въвежда синтаксис, вдъхновен от езици като Ruby и\\n            Python, използвайки отстъпи (whitespace significance) за\\n            дефиниране на блокове вместо къдрави скоби, и заменяйки ключови думи\\n            като\\n            <code>function</code> с по-краткия оператор <code>-&gt;</code>.\\n          </p>\\n          <p>\\n            Всяка програма, написана на CoffeeScript, се превръща в еквивалентен\\n            JavaScript код, който може да бъде изпълнен от всеки съвременен уеб\\n            браузър или Node.js среда. Това го прави мощен инструмент за бърза\\n            разработка (Rapid Prototyping) и писане на по-чист код [1].\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 2. ТРАНСЛАТОР -->\\n        \\n        <section class=\\\"section\\\" id=\\\"translator\\\">\\n          <h2 class=\\\"section-title\\\">2. Що е то Транслатор?</h2>\\n          <p>\\n            В компютърните науки, транслаторът е инструмент, който чете изходен\\n            код, написан на един език за програмиране, и генерира еквивалентен\\n            код на друг език. Този процес често се нарича преобразуване\\n            „източник-към-източник“ (source-to-source converter).\\n          </p>\\n          <figure class=\\\"figure\\\">\\n            <img alt=\\\"Схема на процеса на транслиране\\\" src=\\\"img/transpiler.webp\\\" />\\n            <figcaption>\\n              Фигура 1.1: Процес на транслиране. (Източник: o7planning.org) [3]\\n            </figcaption>\\n          </figure>\\n          <h3>2.1. Видове транслатори</h3>\\n          <p>\\n            Съществува важно разграничение между основните видове транслатори,\\n            базирано на нивото на езиците, които обработват:\\n          </p>\\n          <ul>\\n            <li>\\n              <strong>Компилатор (Compiler):</strong> Използва се за\\n              преобразуване на изходен код, написан на език от високо ниво\\n              (четим от хора), в език от ниско ниво (машинен код), за да се\\n              създадат изпълними програми.\\n            </li>\\n            <li>\\n              <strong>Транспилатор (Transpiler):</strong> Терминът произлиза от\\n              появата на езици като CoffeeScript, TypeScript и Dart.\\n              Транспилаторите преобразуват код от един език от високо ниво (със\\n              строг синтаксис и ясни типове данни) в друг език от високо ниво\\n              (най-често JavaScript).\\n            </li>\\n          </ul>\\n          <h3>2.2. Защо се използват транслатори?</h3>\\n          <p>\\n            Транслаторите и по-специално транспилаторите допринасят значително\\n            за модерната уеб разработка по няколко начина:\\n          </p>\\n          <ul>\\n            <li>\\n              <strong>По-добра поддръжка:</strong> Езиците, които са „насочени\\n              към JavaScript“ (JavaScript-targeted), често предлагат по-добри\\n              инструменти за разработка и поддръжка на големи проекти.\\n            </li>\\n            <li>\\n              <strong>Оптимизация на производителността:</strong> В някои\\n              случаи, части от кодова база могат да бъдат конвертирани към\\n              по-ефективен език. Например, код от Python може да се конвертира\\n              към Fortran за по-добра оптимизация.\\n            </li>\\n            <li>\\n              <strong>Обратна съвместимост (Polyfills):</strong> Транспилатори\\n              като Babel позволяват на програмистите да пишат код с най-новия\\n              синтаксис (ES6+), който след това се конвертира в по-стара версия\\n              (ES5), за да работи на стари браузъри.\\n            </li>\\n          </ul>\\n          <h3>2.3. Примери за известни транслатори</h3>\\n          <figure class=\\\"figure\\\">\\n            <table id=\\\"transpiler-table\\\">\\n              <caption>\\n                Таблица 2.1: Популярни транслатори в уеб разработката\\n              </caption>\\n              <thead>\\n                <tr>\\n                  <th>Име</th>\\n                  <th>Описание</th>\\n                  <th>Употреба</th>\\n                </tr>\\n              </thead>\\n              <tbody>\\n                <tr>\\n                  <td><strong>CoffeeScript</strong></td>\\n                  <td>Преобразува CoffeeScript към JavaScript.</td>\\n                  <td>\\n                    Опростяване на синтаксиса и ускоряване на разработката.\\n                  </td>\\n                </tr>\\n                <tr>\\n                  <td><strong>Babel</strong></td>\\n                  <td>Конвертира модерен JavaScript (ES6+) към ES5.</td>\\n                  <td>Осигуряване на съвместимост със стари браузъри.</td>\\n                </tr>\\n                <tr>\\n                  <td><strong>TypeScript</strong></td>\\n                  <td>Добавя строга типизация към JavaScript.</td>\\n                  <td>\\n                    Мащабни проекти, изискващи надеждност и типова безопасност.\\n                  </td>\\n                </tr>\\n                <tr>\\n                  <td><strong>Dart</strong></td>\\n                  <td>Език, разработен от Google, който се компилира до JS.</td>\\n                  <td>\\n                    Разработка на клиентски приложения (напр. чрез Flutter).\\n                  </td>\\n                </tr>\\n              </tbody>\\n            </table>\\n            <figcaption>\\n              Фигура 2.1: Сравнение на популярни транслатори.\\n            </figcaption>\\n          </figure>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 3. ИСТОРИЯ -->\\n        \\n        <section class=\\\"section\\\" id=\\\"history\\\">\\n          <h2 class=\\\"section-title\\\">\\n            3. История и хронология на CoffeeScript\\n          </h2>\\n          <p>\\n            CoffeeScript е създаден от Jeremy Ashkenas (Джеръми Ашкенас), който\\n            е известен и с разработването на популярната MVC библиотека\\n            Backbone.js [4].\\n          </p>\\n          <p>\\n            Първата публична версия (0.1.0) е представена на 24 декември 2009 г.\\n            [5]. Ашкенас създава езика, за да направи писането на JavaScript\\n            по-приятно и да избегне някои от неговите известни „странности“.\\n            Езикът бързо набира популярност, подпомогната от тогавашната липса на\\n            стандартизиран, по-чист синтаксис в JavaScript (преди ES6).\\n          </p>\\n          <ul>\\n            <li>2010 г.: Излиза версия 1.0.0, която стабилизира синтаксиса.</li>\\n            <li>\\n              2011 г.: Ruby on Rails, един от най-популярните уеб фреймворци, избира\\n              CoffeeScript като език по подразбиране в своята екосистема [6]. Това\\n              дава огромен тласък на приемането на езика в индустрията.\\n            </li>\\n            <li>\\n              2012–2015 г.: Езикът достига своя пик на популярност, използван в\\n              множество големи проекти (като GitHub Atom).\\n            </li>\\n            <li>\\n              След 2015 г.: Популярността намалява с излизането на ECMAScript\\n              2015 (ES6), който въвежда много от предимствата, които CoffeeScript е\\n              популяризирал (класове, стрелкови функции, <code>let/const</code>)\\n              [7].\\n            </li>\\n            <li>\\n              2017 г.: Излиза CoffeeScript 2.0, който вече се компилира към\\n              модерен ES6+ синтаксис, запазвайки краткия CoffeeScript синтаксис,\\n              но използвайки новите JavaScript стандарти [8].\\n            </li>\\n          </ul>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 4. ЦЕЛИ  -->\\n        \\n        <section class=\\\"section\\\" id=\\\"goals\\\">\\n          <h2 class=\\\"section-title\\\">4. Целите на CoffeeScript</h2>\\n          <p>\\n            CoffeeScript е създаден с няколко основни цели, насочени към\\n            подобряване на разработването на уеб приложения [1]:\\n          </p>\\n          <h3>4.1. Краткост и елегантност</h3>\\n          <p>\\n            Основната цел е да се намали количеството код, което трябва да бъде\\n            написано за изпълнение на дадена задача. Чрез премахване на скоби,\\n            точки и запетаи и използване на интуитивни синтактични елементи,\\n            CoffeeScript позволява на разработчиците да се фокусират върху\\n            логиката, а не върху синтаксиса [1].\\n          </p>\\n          <h3>4.2. Избягване на проблемите на JavaScript</h3>\\n          <p>\\n            Езикът автоматично имплементира добри практики, които предотвратяват\\n            често срещани грешки в JavaScript, като например:\\n          </p>\\n          <ul>\\n            <li>\\n              Автоматично капсулиране на целия код във функция с незабавно\\n              изпълнение (IIFE), за да се избегне замърсяване на глобалното\\n              пространство [1].\\n            </li>\\n            <li>\\n              Използване на <code>=&gt;</code> (fat arrow) за автоматично\\n              обвързване на ключовата дума <code>this</code> към обхвата на\\n              функцията, решавайки често срещан проблем с обекти и асинхронни\\n              операции [9].\\n            </li>\\n            <li>\\n              Улеснено боравене с <code>null</code> и\\n              <code>undefined</code> чрез оператора за съществуване\\n              (<code>?</code>).\\n            </li>\\n          </ul>\\n          <h3>4.3. Съвместимост с ООП парадигмата</h3>\\n          <p>\\n            Въвежда синтаксис за класове и наследяване, който е по-интуитивен и\\n            познат на програмисти, идващи от езици като Java, C# или Ruby.\\n            Въпреки че JavaScript е базиран на прототипи, CoffeeScript\\n            предоставя лесна за разбиране абстракция върху този механизъм [1].\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 5. СИНТАКСИС -->\\n        \\n        <section class=\\\"section\\\" id=\\\"syntax\\\">\\n          <h2 class=\\\"section-title\\\">5. Основни синтактични конструкции</h2>\\n          <p>\\n            Синтаксисът на CoffeeScript е изключително минималистичен, като\\n            използва отстъпи (indentation) за структура, заменяйки\\n            къдравите скоби на JavaScript.\\n          </p>\\n          <!-- 5.1 Функции -->\\n          <h3>5.1. Функции</h3>\\n          <p>\\n            Функциите се дефинират с оператора стрелка (<code>-&gt;</code>).\\n            Тялото на функцията използва отстъпи, а резултатът от последния\\n            ред се връща като резултат от изпълнението на функцията (implicit\\n            return) [1].\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>square = (x) -&gt; x * x\\ncube   = (x) -&gt; square(x) * x</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var cube, square;\\n\\nsquare = function(x) {\\n  return x * x;\\n};\\n\\ncube = function(x) {\\n  return square(x) * x;\\n};</code></pre>\\n            </div>\\n          </div>\\n          <p>\\n            Функциите също така могат да имат и аргументи по подразбиране, в\\n            случай когато последните не са зададени.\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>fill = (container, liquid = \\\"coffee\\\") -&gt;\\n  \\\"Filling the #{container} with #{liquid}...\\\"</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var fill;\\n\\nfill = function(container, liquid = \\\"coffee\\\") {\\n  return `Filling the ${container} with ${liquid}...`;\\n};</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.2 Низове -->\\n          <h3>5.2. Низове</h3>\\n          <p>\\n            CoffeeScript поддържа интерполация на променливи в низове с двойни\\n            кавички чрез синтаксиса <code>#{}</code>. Също така се допуска\\n            използването на многоредови низове.\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>poem = \\\"\\\"\\\"\\n  The rain in Spain\\n  stays mainly in the plain.\\n\\\"\\\"\\\"\\n\\nauthor = \\\"Trevor Burnham\\\"\\nquote = \\\"Code is #{poem} -- #{author}.\\\"</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var author, poem, quote;\\n\\npoem = \\\"The rain in Spain\\\\nstays mainly in the plain.\\\\n\\\";\\n\\nauthor = \\\"Trevor Burnham\\\";\\n\\nquote = \\\"Code is \\\" + poem + \\\" -- \\\" + author + \\\".\\\";</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.3 Обекти и масиви -->\\n          <h3>5.3. Обекти и масиви</h3>\\n          <p>\\n            Къдравите скоби (за обекти) и запетаите са опционални при използване\\n            на отстъпи и нови редове. Това прави дефинирането на структури от\\n            данни много по-кратко [1].\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>song =\\n  title: \\\"Rhapsody\\\"\\n  artist: \\\"Queen\\\"\\n  tags: [\\n    \\\"rock\\\"\\n    \\\"opera\\\"\\n    \\\"classic\\\"\\n  ]</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var song;\\n\\nsong = {\\n  title: \\\"Rhapsody\\\",\\n  artist: \\\"Queen\\\",\\n  tags: [\\\"rock\\\", \\\"opera\\\", \\\"classic\\\"]\\n};</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.4 Коментари -->\\n          <h3>5.4. Коментари</h3>\\n          <p>\\n            В CoffeeScript коментарите се отбелязват със знака <code>#</code> до\\n            края на реда или с <code>###</code>, продължаващи до следващата\\n            поява на <code>###</code>. Коментарите се игнорират от компилатора,\\n            въпреки че той полага усилия да ги включи отново в генерирания\\n            JavaScript след компилацията.\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>###\\nFortune Cookie Reader v1.0\\nReleased under the MIT License\\n###\\n\\nsayFortune = (fortune) -&gt;\\n  console.log fortune # in bed!</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>/*\\nFortune Cookie Reader v1.0\\nReleased under the MIT License\\n*/\\nvar sayFortune;\\n\\nsayFortune = function(fortune) {\\n  return console.log(fortune); // in bed!\\n};</code></pre>\\n            </div>\\n          </div>\\n          <p>\\n            Вградените коментари с <code>###</code> позволяват използването на\\n            типови анотации.\\n          </p>\\n          <!-- 5.5 Scope -->\\n          <h3>5.5. Област на видимост (Scope)</h3>\\n          <p>\\n            CoffeeScript автоматично капсулира целия код във функция с незабавно\\n            изпълнение (IIFE) и автоматично дефинира променливите с\\n            <code>var</code> (или <code>let</code>/<code>const</code> в CS 2.0),\\n            за да предотврати замърсяване на глобалното пространство [1].\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>outer = 1\\n\\nchangeNumbers = -&gt;\\n  inner = -1\\n  outer = 10\\n\\ninner = changeNumbers()</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var changeNumbers, inner, outer;\\n\\nouter = 1;\\n\\nchangeNumbers = function() {\\n  var inner;\\n  inner = -1;\\n  return outer = 10;\\n};\\n\\ninner = changeNumbers();</code></pre>\\n            </div>\\n          </div>\\n          <p>\\n            Обърнете внимание как всички декларации на променливи са изтеглени\\n            нагоре до върха на най-близката област на видимост (scope), в която\\n            се използват за пръв път. Променливата <code>outer</code> не се\\n            декларира повторно във вътрешната функция, тъй като тя вече\\n            се обхваща (сe използва); <code>inner</code> във функцията, от друга страна, не би\\n            трябвало да може да променя стойността на външната променлива със\\n            същото име (още не е използвана) и следователно има собствена декларация. Тъй като няма\\n            пряк достъп до ключовата дума <code>var</code>, е невъзможно\\n            умишлено да засенчим (shadow) външна променлива. \\n          </p>\\n          <!-- 5.6 Условни оператори -->\\n          <h3>5.6. Условни оператори</h3>\\n          <p>\\n            Условните конструкции използват ключовите думи <code>if</code>,\\n            <code>else</code>, <code>unless</code>. Те могат да бъдат използвани\\n            в ин-фикс и пост-фикс форма (след израза) [1].\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>speed = 0\\nspeed = 10 unless speed?\\n\\nif speed &lt; 10\\n  status = \\\"slow\\\"\\nelse if speed &lt; 50\\n  status = \\\"normal\\\"\\nelse\\n  status = \\\"fast\\\"</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var speed, status;\\n\\nspeed = 0;\\nif (speed == null) {\\n  speed = 10;\\n}\\n\\nif (speed &lt; 10) {\\n  status = \\\"slow\\\";\\n} else if (speed &lt; 50) {\\n  status = \\\"normal\\\";\\n} else {\\n  status = \\\"fast\\\";\\n}</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.7 Цикли и List Comprehensions -->\\n          <h3>5.7. Цикли и обхвати (list comprehensions)</h3>\\n          <p>\\n            Циклите се дефинират чрез <code>for</code>. Списъчните обхвати\\n            (List Comprehensions) позволяват трансформиране на масиви с един ред\\n            код [1].\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code># Eat lunch.\\neat = (food) -&gt; \\\"#{food} eaten.\\\"\\neat food for food in [\'toast\', \'cheese\', \'wine\']\\n\\n# Fine five course dining.\\ncourses = [\'greens\', \'caviar\', \'truffles\', \'roast\', \'cake\']\\nmenu = (i, dish) -&gt; \\\"Menu Item #{i}: #{dish}\\\"\\nmenu i + 1, dish for dish, i in courses\\n\\n# Health conscious meal.\\nfoods = [\'broccoli\', \'spinach\', \'chocolate\']\\neat food for food in foods when food isnt \'chocolate\'</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>// Eat lunch.\\nvar courses, dish, eat, food, foods, i, j, k, l, len, len1, len2, menu, ref;\\n\\neat = function(food) {\\n  return `${food} eaten.`;\\n};\\n\\nref = [\'toast\', \'cheese\', \'wine\'];\\nfor (j = 0, len = ref.length; j &lt; len; j++) {\\n  food = ref[j];\\n  eat(food);\\n}\\n\\n// Fine five course dining.\\ncourses = [\'greens\', \'caviar\', \'truffles\', \'roast\', \'cake\'];\\n\\nmenu = function(i, dish) {\\n  return `Menu Item ${i}: ${dish}`;\\n};\\n\\nfor (i = k = 0, len1 = courses.length; k &lt; len1; i = ++k) {\\n  dish = courses[i];\\n  menu(i + 1, dish);\\n}\\n\\n// Health conscious meal.\\nfoods = [\'broccoli\', \'spinach\', \'chocolate\'];\\n\\nfor (l = 0, len2 = foods.length; l &lt; len2; l++) {\\n  food = foods[l];\\n  if (food !== \'chocolate\') {\\n    eat(food);\\n  }\\n}</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.8 Изрази -->\\n          <h3>5.8. Изрази (Expressions)</h3>\\n          <p>\\n            В CoffeeScript почти всичко е <strong>израз (expression)</strong>,\\n            за разлика от JavaScript, където много управляващи инструкции (като\\n            <code>if</code>, <code>switch</code> и <code>for</code>) са само\\n            инструкции (statements) и не връщат стойност. Тази концепция прави\\n            кода по-функционален и позволява на програмиста да присвоява\\n            резултата от цял контролен блок на променлива.\\n          </p>\\n          <p>\\n            Например, <code>if/else</code> блокът автоматично връща стойност,\\n            елиминирайки нуждата от тернарен оператор (<code>? :</code>) за\\n            просто присвояване. Това важи и за циклите, където, както беше\\n            показано в предишната секция, те могат да връщат масиви (List\\n            Comprehensions).\\n          </p>\\n          <p>\\n            Въпреки че не добавяме оператори <code>return</code> към\\n            CoffeeScript функциите, те все пак връщат своята финална стойност.\\n            Компилаторът на CoffeeScript се стреми да гарантира, че всички\\n            инструкции в езика могат да бъдат използвани като изрази\\n            (expressions).\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>grade = (student) -&gt;\\n  if student.excellentWork\\n    \\\"A+\\\"\\n  else if student.okayStuff\\n    if student.triedHard then \\\"B\\\" else \\\"B-\\\"\\n  else\\n    \\\"C\\\"\\n\\neldest = if 24 &gt; 21 then \\\"Liz\\\" else \\\"Ike\\\"</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var eldest, grade;\\n\\ngrade = function(student) {\\n  if (student.excellentWork) {\\n    return \\\"A+\\\";\\n  } else if (student.okayStuff) {\\n    if (student.triedHard) {\\n      return \\\"B\\\";\\n    } else {\\n      return \\\"B-\\\";\\n    }\\n  } else {\\n    return \\\"C\\\";\\n  }\\n};\\n\\neldest = 24 &gt; 21 ? \\\"Liz\\\" : \\\"Ike\\\";</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.9 Оператори -->\\n          <h3>5.9. Оператори</h3>\\n          <p>\\n            CoffeeScript замества някои символни оператори с по-четливи думи\\n            (напр. <code>is</code>, <code>not</code>, <code>and</code>,\\n            <code>or</code>).\\n          </p>\\n          <figure class=\\\"figure\\\">\\n            <table id=\\\"operator-table\\\">\\n              <caption>\\n                Таблица 5.9: Сравнение на основните оператори в CoffeeScript и\\n                JavaScript ES5 [1]\\n              </caption>\\n              <thead>\\n                <tr>\\n                  <th>CoffeeScript</th>\\n                  <th>JavaScript Еквивалент</th>\\n                </tr>\\n              </thead>\\n              <tbody>\\n                <tr>\\n                  <td><code>is</code></td>\\n                  <td><code>===</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>isnt</code></td>\\n                  <td><code>!==</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>not</code></td>\\n                  <td><code>!</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>and</code></td>\\n                  <td><code>&amp;&amp;</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>or</code></td>\\n                  <td><code>||</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>true</code>, <code>yes</code>, <code>on</code></td>\\n                  <td><code>true</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>false</code>, <code>no</code>, <code>off</code></td>\\n                  <td><code>false</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>@</code>, <code>this</code></td>\\n                  <td><code>this</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>a in b</code></td>\\n                  <td>\\n                    <code>[].indexOf.call(b, a) &gt;= 0</code> (Проверка за принадлежност)\\n                  </td>\\n                </tr>\\n                <tr>\\n                  <td><code>a of b</code></td>\\n                  <td><code>a in b</code> (Проверка за наличие на ключ в обект)</td>\\n                </tr>\\n                <tr>\\n                  <td><code>for a from b</code></td>\\n                  <td><code>for (a of b)</code> (Итериране по ключове)</td>\\n                </tr>\\n                <tr>\\n                  <td><code>a ** b</code></td>\\n                  <td><code>Math.pow(a, b)</code> (Степенуване)</td>\\n                </tr>\\n                <tr>\\n                  <td><code>a // b</code></td>\\n                  <td><code>Math.floor(a / b)</code> (Целочислено деление)</td>\\n                </tr>\\n                <tr>\\n                  <td><code>a %% b</code></td>\\n                  <td>\\n                    <code>(a % b + b) % b</code> (Оператор за деление с остатък с коректно\\n                    поведение при отрицателни числа)\\n                  </td>\\n                </tr>\\n              </tbody>\\n            </table>\\n            <figcaption>\\n              Фигура 5.9: Оператори, които CoffeeScript трансформира за по-добра\\n              четимост или функционалност. [1]\\n            </figcaption>\\n          </figure>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code># Четливи оператори\\nif a is b and not c\\n  alert \'ok\'\\n\\n# Оператор за съществуване\\nvelocity =\\n  speed: 10 if car?\\n\\nname = user?.name</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var name, velocity;\\n\\nif (a === b &amp;&amp; !c) {\\n  alert(\'ok\');\\n}\\n\\nif (typeof car !== \\\"undefined\\\" &amp;&amp; car !== null) {\\n  velocity = {\\n    speed: 10\\n  };\\n}\\n\\nname = typeof user !== \\\"undefined\\\" &amp;&amp; user !== null ? user.name : void 0;</code></pre>\\n            </div>\\n          </div>\\n          <p>\\n            Операторът за съществуване (Existential Operator) <code>?</code> се\\n            използва за безопасен достъп до свойства [1].\\n          </p>\\n          <!-- 5.10 Класове -->\\n          <h3>5.10. Класове</h3>\\n          <p>\\n            CoffeeScript 1 предоставя ключовите думи <code>class</code> и\\n            <code>extends</code> като синтактичен елемент (syntactic sugar) за\\n            работа с прототипни функции. С навлизането на ES2015 JavaScript\\n            възприе тези ключови думи; затова CoffeeScript 2 компилира своите\\n            ключови думи <code>class</code> и <code>extends</code> към класове в\\n            ES2015.\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>class Animal\\n  constructor: (@name) -&gt;\\n\\n  move: (meters) -&gt;\\n    alert \\\"#{@name} moved #{meters}m.\\\"\\n\\nclass Snake extends Animal\\n  move: -&gt;\\n    alert \\\"Slithering...\\\"\\n    super 5\\n\\nclass Horse extends Animal\\n  move: -&gt;\\n    alert \\\"Galloping...\\\"\\n    super 45\\n\\nsam = new Snake \\\"Sammy the Python\\\"\\ntom = new Horse \\\"Tommy the Palomino\\\"\\n\\nsam.move()\\ntom.move()</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript (част)</div>\\n              <pre><code>var Animal, Horse, Snake, sam, tom;\\n\\nAnimal = class Animal {\\n  constructor(name) {\\n    this.name = name;\\n  }\\n\\n  move(meters) {\\n    return alert(this.name + ` moved ${meters}m.`);\\n  }\\n};\\n\\nSnake = class Snake extends Animal {\\n  move() {\\n    alert(\\\"Slithering...\\\");\\n    return super.move(5);\\n  }\\n};\\n\\nHorse = class Horse extends Animal {\\n  move() {\\n    alert(\\\"Galloping...\\\");\\n    return super.move(45);\\n  }\\n};\\n\\nsam = new Snake(\\\"Sammy the Python\\\");\\ntom = new Horse(\\\"Tommy the Palomino\\\");\\n\\nsam.move();\\ntom.move();</code></pre>\\n            </div>\\n          </div>\\n          <!-- 5.11 Типови анотации -->\\n          <h3>5.11. Типови анотации</h3>\\n          <p>\\n            Статичното проверяване на типове може да бъде постигнато в\\n            CoffeeScript използвайки\\n            <a\\n              href=\\\"https://flow.org/en/docs/types/comments/\\\"\\n              rel=\\\"noopener noreferrer\\\"\\n              target=\\\"_blank\\\"\\n              >Comment Types syntax</a\\n            >\\n            на\\n            <a\\n              href=\\\"https://flow.org/\\\"\\n              rel=\\\"noopener noreferrer\\\"\\n              target=\\\"_blank\\\"\\n              >Flow</a\\n            >.\\n          </p>\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code># @flow\\n\\n###::\\ntype Obj = {\\n  num: number,\\n};\\n###\\n\\nfn = (str ###: string ###, obj ###: Obj ###) ###: string ### -&gt;\\n  str + obj.num</code></pre>\\n            </div>\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript (част)</div>\\n              <pre><code>// @flow\\n/*::\\ntype Obj = {\\n  num: number,\\n};\\n*/\\nvar fn;\\n\\nfn = function(str/*: string */, obj/*: Obj */)/*: string */ {\\n  return str + obj.num;\\n};</code></pre>\\n            </div>\\n          </div>\\n          <p>\\n            CoffeeScript не извършва никаква проверка на типове сам по себе си;\\n            JavaScript резултатът, който виждате по-горе, трябва да бъде подаден\\n            към Flow, за да може то да валидира вашия код.\\n          </p>\\n          <pre\\n            class=\\\"inline-pre\\\"\\n          ><code>coffee --bare --no-header --compile app.coffee &amp;&amp; npm run flow</code></pre>\\n          <p>\\n            Опциите <code>--bare</code> и <code>--no-header</code> са важни,\\n            защото Flow изисква първият ред на файла да бъде коментарът\\n            <code>// @flow</code>.\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 6. РАЗЛИКИ С JS -->\\n        \\n        <section class=\\\"section\\\" id=\\\"differences\\\">\\n          <h2 class=\\\"section-title\\\">\\n            6. Разлики и предимства спрямо JavaScript\\n          </h2>\\n          <p>\\n            CoffeeScript служи като интерпретативен слой, който добавя\\n            синтактични предимства, липсващи в ранните версии на JavaScript.\\n          </p>\\n          <h3>6.1. Синтактични предимства (Syntactic Sugar)</h3>\\n          <p>\\n            CoffeeScript превъзхожда JavaScript по краткост и чистота на\\n            синтаксиса.\\n          </p>\\n          <figure class=\\\"figure\\\">\\n            <table id=\\\"table-6-1\\\">\\n              <caption>\\n                Таблица 6.1: Директно сравнение на синтаксиса\\n              </caption>\\n              <thead>\\n                <tr>\\n                  <th>Характеристика</th>\\n                  <th>CoffeeScript</th>\\n                  <th>JavaScript (ES5)</th>\\n                </tr>\\n              </thead>\\n              <tbody>\\n                <tr>\\n                  <td>Дефиниране на функция</td>\\n                  <td><code>(a, b) -&gt; a + b</code></td>\\n                  <td><code>function(a, b) { return a + b; }</code></td>\\n                </tr>\\n                <tr>\\n                  <td>Оператор за съществуване</td>\\n                  <td><code>user?.name</code></td>\\n                  <td><code>(user != null ? user.name : undefined)</code></td>\\n                </tr>\\n                <tr>\\n                  <td><code>this</code> обвързване</td>\\n                  <td><code>log = =&gt; console.log @message</code></td>\\n                  <td>\\n                    <code\\n                      >var _this = this; this.log = function() { return\\n                      _this.message; };</code\\n                    >\\n                  </td>\\n                </tr>\\n                <tr>\\n                  <td>Сравнение на равенство</td>\\n                  <td><code>if a is b</code></td>\\n                  <td><code>if (a === b)</code></td>\\n                </tr>\\n              </tbody>\\n            </table>\\n            <figcaption>\\n              Фигура 6.1: Основни разлики между CoffeeScript и JavaScript ES5.\\n              [1], [9]\\n            </figcaption>\\n          </figure>\\n          <h3>6.2. Предимства при разработване</h3>\\n          <ul>\\n            <li>\\n              По-малко грешки при обхвата: Автоматичното избягване на глобални\\n              променливи и ясният синтаксис за обвързване на\\n              <code>this</code> намаляват често срещаните грешки.\\n            </li>\\n            <li>\\n              По-висока производителност: Позволява на разработчиците да пишат код по-бързо.\\n            </li>\\n            <li>\\n              Чист изходен JavaScript: Компилаторът гарантира, че генерираният\\n              JavaScript е чист, добре форматиран и се придържа към добрите\\n              практики [1].\\n            </li>\\n          </ul>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n\\n        <!--7. ПРАКТИЧЕСКИ ПРИМЕРИ -->\\n        \\n        <section class=\\\"section\\\" id=\\\"practical-examples\\\">\\n          <h2 class=\\\"section-title\\\">7. Малък уеб-сървър на CoffeeScript</h2>\\n\\n          <p>\\n            Следва пример за <strong>минимален JSON API сървър</strong> на\\n            Node.js, който обслужва един endpoint:\\n            <code>GET /api/echo?msg=...</code>. Ако параметърът\\n            <code>msg</code> липсва, връща стойност по подразбиране.\\n          </p>\\n\\n          <p>\\n            Важно е да се обърне внимание как CoffeeScript прави същата логика\\n            по-кратка чрез:\\n            <strong>отстъпи</strong>,\\n            <strong>implicit return</strong>, оператора за съществуване\\n            <code>?</code>, и по-четливи оператори като <code>is</code> /\\n            <code>yes</code>. [1] В JavaScript (ES5) същото изисква повече „шум“\\n            — фигурни скоби, <code>var</code>, повече проверки за\\n            <code>null/undefined</code>.\\n          </p>\\n\\n          <div class=\\\"code-pair\\\">\\n            <div class=\\\"code-block coffeescript\\\">\\n              <div class=\\\"code-caption\\\">CoffeeScript</div>\\n              <pre><code>http = require \'http\'\\nurl  = require \'url\'\\n\\nsend = (res, code, obj) -&gt;\\n  res.writeHead code, {\'Content-Type\': \'application/json; charset=utf-8\'}\\n  res.end JSON.stringify obj\\n\\nserver = http.createServer (req, res) -&gt;\\n  {pathname, query} = url.parse req.url, true\\n\\n  if req.method is \'GET\' and pathname is \'/api/echo\'\\n    msg = query.msg ? \'Hello\'\\n    obj =\\n      ok: yes\\n      echo: msg\\n      at: Data.now()\\n\\n    send res, 200, obj\\n  else\\n    obj =\\n      ok: no\\n      error: \'Not found\'\\n\\n    send res, 404, obj\\n\\nserver.listen 3000, () -&gt; console.log \'http://localhost:3000\'</code></pre>\\n            </div>\\n\\n            <div class=\\\"code-block javascript\\\">\\n              <div class=\\\"code-caption\\\">Еквивалентен JavaScript</div>\\n              <pre><code>var http = require(\'http\');\\nvar url = require(\'url\');\\n\\nfunction send(res, code, obj) {\\n  res.writeHead(code, {\'Content-Type\': \'application/json; charset=utf-8\'});\\n  res.end(JSON.stringify(obj));\\n}\\n\\nvar server = http.createServer(function(req, res) {\\n  var parsed = url.parse(req.url, true);\\n  var pathname = parsed.pathname;\\n  var query = parsed.query;\\n\\n  if (req.method === \'GET\' &amp;&amp; pathname === \'/api/echo\') {\\n    var msg = (query &amp;&amp; query.msg != null) ? query.msg : \'Hello\';\\n    var obj = {\\n      ok: true,\\n      echo: msg,\\n      at: Data.now()\\n    }\\n\\n    send(res, 200, obj);\\n  } else {\\n    var obj = {\\n      ok: false,\\n      error: \'Not found\'\\n    }\\n\\n    send(res, 404, obj);\\n  }\\n});\\n\\nserver.listen(3000, function() {\\n  console.log(\'http://localhost:3000\');\\n});</code></pre>\\n            </div>\\n          </div>\\n\\n          <p>\\n            Тестване (пример): отворете\\n            <code>http://localhost:3000/api/echo?msg=Zdravei</code> и ще\\n            получите JSON отговор. При липсващ <code>msg</code> ще получите\\n            <code>\\\"Hello\\\"</code> по подразбиране. И в двата варианта логиката е\\n            една и съща, разликата е в „плътността“ на синтаксиса.\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 8. ПРИЛОЖЕНИЯ -->\\n        \\n        <section class=\\\"section\\\" id=\\\"applications\\\">\\n          <h2 class=\\\"section-title\\\">\\n            8. Примери на съществуващи приложения или сайтове, които използват\\n            CoffeeScript\\n          </h2>\\n          <p>\\n            CoffeeScript е бил жизненоважен инструмент в разработката на няколко\\n            значими софтуерни продукта и платформи:\\n          </p>\\n          <ul>\\n            <li>\\n              GitHub Atom Editor: Ранните версии на популярния текстов редактор\\n              на GitHub са базирани на CoffeeScript [10].\\n            </li>\\n            <li>\\n              Ruby on Rails: В продължение на години CoffeeScript беше\\n              стандартната опция за скриптове на клиентската страна, интегриран\\n              дълбоко в Rails asset pipeline [6].\\n            </li>\\n            <li>\\n              Discourse: Платформата за дискусии и форуми с отворен код,\\n              създадена от Джеф Атууд (Jeff Atwood), активно използва\\n              CoffeeScript за клиентския си код [11].\\n            </li>\\n            <li>\\n              DocuSign: Компанията за електронни подписи е използвала\\n              CoffeeScript в голяма част от своята фронтенд база преди\\n              миграцията към TypeScript [12].\\n            </li>\\n          </ul>\\n          <p>\\n            Тези примери подчертават ролята на CoffeeScript като зрял и надежден\\n            език, подходящ за големи, мащабируеми проекти, където чистотата на\\n            кода е от първостепенно значение.\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 9. ТЪЖНАТА ИСТИНА  -->\\n        \\n        <section class=\\\"section\\\" id=\\\"the-sad-truth\\\">\\n          <h2 class=\\\"section-title\\\">9. Тъжната истина за езика CoffeeScript</h2>\\n          <p>\\n            Въпреки своята елегантност и значителна роля в историята на уеб\\n            разработката,\\n            <strong>CoffeeScript загуби доминиращата си позиция</strong> на\\n            пазара след 2015 г. Причините за този спад са комплексни и са пряко\\n            свързани с еволюцията на самия JavaScript.\\n          </p>\\n          <h3>9.1. Причини за загубата на популярност</h3>\\n          <ul>\\n            <li>\\n              <strong>Появата на ES6 (ECMAScript 2015):</strong> Най-големият\\n              конкурент на CoffeeScript се оказа самият JavaScript. ES6 въведе\\n              <strong>нативни</strong> функции като стрелкови функции (Arrow\\n              Functions), класове (Classes), <code>let</code> и\\n              <code>const</code>, които бяха основните „синтактични елементи“,\\n              предлагани от CoffeeScript. Щом те станаха част от стандарта,\\n              нуждата от външен транспилатор за постигане на елегантен синтаксис\\n              намаля драстично.\\n            </li>\\n            <li>\\n              <strong>Възходът на TypeScript:</strong> Другият основен\\n              конкурент, <strong>TypeScript (TS)</strong>, се фокусира върху\\n              решаването на по-голям проблем. Докато\\n              CoffeeScript предлагаше синтактично опростяване, TypeScript\\n              предложи <strong>типова безопасност (Type Safety)</strong> и\\n              <strong>мащабируемост</strong>. За големи корпоративни проекти,\\n              възможността за откриване на грешки още по време на писане\\n              (Compile-Time) и подобряването на инструментите за автодопълване и\\n              рефакторинг (IDE Tooling) се оказаха по-ценни от краткия\\n              синтаксис.\\n            </li>\\n            <li>\\n              <strong>Трудности при дебъгване (Debugging):</strong> Когато се\\n              налага дебъгване, разработчиците трябва да преминат през\\n              генерирания JavaScript код, който, въпреки че е чист, не е\\n              идентичен с написания CoffeeScript. Това добавя допълнителна\\n              сложност, особено в ранните години на езика.\\n            </li>\\n            <li>\\n              <strong>Опасения при наемане (Hiring Concerns):</strong> С\\n              намаляването на популярността, за компаниите ставаше по-трудно да\\n              намират нови разработчици, които са запознати с CoffeeScript,\\n              предпочитайки да работят с чист ES6+ или TypeScript.\\n            </li>\\n          </ul>\\n          <h3>9.2. Статистика от пазара</h3>\\n          <p>\\n            Тенденциите в индустрията ясно показват изместването. Докато около\\n            2012–2015 г. CoffeeScript беше основна тема в GitHub и блоговете за\\n            разработка, след 2016 г. той беше почти напълно засенчен от\\n            TypeScript и напредъка на ES6.\\n          </p>\\n          <ul>\\n            <li>\\n              <strong>TypeScript:</strong> Приет от големи компании като Google\\n              (Angular), Microsoft (който го създава) и Facebook (който го\\n              използва в някои проекти), той бързо се превръща в\\n              <strong>стандарт за мащабируема разработка</strong>.\\n            </li>\\n            <li>\\n              <strong>CoffeeScript:</strong> Днес се поддържа от малка, но\\n              лоялна общност (CoffeeScript 2), като се използва предимно за\\n              по-малки проекти или в стари кодови бази, които все още не са\\n              мигрирали.\\n            </li>\\n          </ul>\\n          <div class=\\\"video-container\\\">\\n            <iframe\\n              height=\\\"315\\\"\\n              referrerpolicy=\\\"strict-origin-when-cross-origin\\\"\\n              src=\\\"https://www.youtube.com/embed/Ae4h9GC9cCg\\\"\\n              title=\\\"YouTube video player: TypeScript vs. CoffeeScript vs. ES6\\\"\\n              width=\\\"560\\\"\\n            >\\n            </iframe>\\n          </div>\\n          <p>\\n            Този видеоклип, публикуван през 2015 г., е направен точно в момента,\\n            когато започва историческият преход и обяснява защо\\n            <strong>технологичното предимство на TypeScript надделява над\\n              синтактичната елегантност на CoffeeScript</strong>.\\n          </p>\\n        </section>\\n        <hr class=\\\"divider\\\" />\\n        \\n        <!-- 10. ИЗТОЧНИЦИ -->\\n        \\n        <section class=\\\"section citation-list\\\" id=\\\"citations\\\">\\n          <h2 class=\\\"section-title\\\">10. Списък от източници</h2>\\n          <ol>\\n            <li>\\n              Jeremy Ashkenas, \\\"CoffeeScript: The little language that compiles\\n              into JavaScript\\\",\\n              [https://coffeescript.org/], последно посетен на 2025-12-03.\\n            </li>\\n            <li>\\n              Jeremy Ashkenas, \\\"CoffeeScript Source Code - README\\\",\\n              [https://github.com/jashkenas/coffeescript/blob/main/README.md],\\n              последно посетен на 2025-12-17.\\n            </li>\\n            <li>\\n              Duy Nguyen, \\\"What is Transpiler?\\\",\\n              [https://o7planning.org/14149/what-is-transpiler], последно\\n              посетен на 2025-12-09.\\n            </li>\\n            <li>\\n              Jeremy Ashkenas, \\\"Backbone.js\\\",\\n              [https://backbonejs.org/], последно посетен на 2025-12-21.\\n            </li>\\n            <li>\\n              Wikipedia contributors, \\\"CoffeeScript\\\",\\n              [https://en.wikipedia.org/wiki/CoffeeScript], последно посетен на\\n              2025-12-12.\\n            </li>\\n            <li>\\n              David Heinemeier Hansson, \\\"Rails is omakase\\\", публикуван Dec\\n              27 2012, [https://dhh.dk/2012/rails-is-omakase.html], последно\\n              посетен на 2025-12-05.\\n            </li>\\n            <li>\\n              Axel Rauschmayer, \\\"The State of JavaScript\\\", публикуван Aug\\n              24 2016,\\n              [https://2ality.com/2016/08/the-state-of-javascript.html],\\n              последно посетен на 2025-12-18.\\n            </li>\\n            <li>\\n              Jeremy Ashkenas, \\\"CoffeeScript 2\\\", публикуван Sep\\n              18 2017, [https://coffeescript.org/v2/], последно посетен на\\n              2025-12-02.\\n            </li>\\n            <li>\\n              Andy E, \\\"What is the difference between -&gt; and =&gt; in\\n              CoffeeScript?\\\",\\n              [https://stackoverflow.com/questions/28519713/what-is-the-difference-between-and-in-coffeescript],\\n              последно посетен на 2025-12-14.\\n            </li>\\n            <li>\\n              GitHub, \\\"Atom\\\",\\n              [https://github.com/atom/atom], последно посетен на 2025-12-23.\\n            </li>\\n            <li>\\n              Discourse Meta, \\\"What is Discourse?\\\",\\n              [https://meta.discourse.org/t/what-is-discourse/30555], последно\\n              посетен на 2025-12-07.\\n            </li>\\n            <li>\\n              Daniel G. Rodriguez, \\\"Migrating from CoffeeScript to TypeScript at\\n              DocuSign\\\",\\n              [https://www.docusign.com/blog/developers/migrating-from-coffeescript-to-typescript-at-docusign/],\\n              последно посетен на 2025-12-20.\\n            </li>\\n          </ol>\\n        </section>\\n      </article>\\n    </main>\\n\\n    <footer class=\\\"site-footer\\\">\\n      <p>*При изработването на реферата е бил използван изкуствен интелект за генериране на CSS стилове.</p>\\n   </footer>\\n  </body>\\n</html>\\n\",\"error\":0,\"size\":57909}],\"settings\":{\"page\":{\"page_size\":\"a4\",\"orientation\":\"portrait\",\"page_width\":210,\"page_height\":297,\"margin\":18,\"font_size\":12,\"line_spacing\":1,\"words\":0,\"lines\":0},\"pagination\":{\"show_page_numbers\":1,\"no_number_on_first\":1,\"page_number_pos\":\"footer\",\"page_number_format\":\"roman-upper\",\"page_number_template\":\"{file} • стр. {page}\",\"line_numbers_mode\":\"none\",\"line_numbers_placement\":\"\"},\"sections\":{\"new_page_on_header\":1,\"header_page_break_levels\":[2],\"new_page_on_file\":0,\"file_name_as_section\":0,\"wrap_lines\":\"yes\"}},\"meta\":{\"title\":\"\",\"author\":\"\",\"course\":\"\",\"citation_template\":\"\",\"metadata_placement\":\"none\",\"statistics_placement\":\"end\"},\"stats\":{\"pages\":27,\"lines\":996,\"words\":3185,\"avg_lines\":\"36.89\"}}', '2026-01-27 20:06:16', '2026-01-28 18:34:07');
INSERT INTO `projects` (`id`, `user_id`, `name`, `payload`, `created_at`, `updated_at`) VALUES
(4, 3, 'test', '{\"htmls\":[{\"name\":\"test.html\",\"type\":\"text/text/html\",\"html\":\"<!doctype html>\\n<html lang=\\\"bg\\\">\\n<head>\\n  <meta charset=\\\"utf-8\\\" />\\n  <title>Тестов документ</title>\\n</head>\\n<body>\\n\\n<h1>Тестов документ (H1)</h1>\\n<p>\\n  Това е кратък параграф с <strong>удебелен текст</strong>, <em>наклонен текст</em>,\\n  <i>курсив</i> и <u>подчертан текст</u>.\\n</p>\\n\\n<hr />\\n\\n<h2>Секция 1 (H2)</h2>\\n<p>\\n  Тук имаме по-дълъг текст, който трябва да се wrap-ва според ширината на страницата.\\n  Целта е да се види дали при промяна на размера на шрифта редовете се преразпределят коректно.\\n</p>\\n\\n<p>Параграф преди списък:</p>\\n\\n<ul>\\n  <li>Първи елемент със <strong>strong</strong> и <em>em</em></li>\\n  <li>Втори елемент (ul)</li>\\n  <li>Трети елемент с <u>underline</u></li>\\n</ul>\\n\\n<ol>\\n  <li>Първи елемент (ol) — трябва да се рендерира като bullet</li>\\n  <li>Втори елемент (ol)</li>\\n</ol>\\n\\n<p>\\n  Празни редове за тест:\\n</p>\\n\\n<br><br><br>\\n\\n<h3>Код блок (H3)</h3>\\n\\n<pre><code>function hello(name) {\\n  console.log(\\\"Hello, \\\" + name);\\n}\\n\\nfor (let i = 0; i &lt; 3; i++) {\\n  hello(\\\"User \\\" + i);\\n}</code></pre>\\n\\n<p>\\n  Край на тестовия документ.\\n</p>\\n\\n</body>\\n</html>\\n\",\"error\":0,\"size\":1465}],\"settings\":{\"page\":{\"page_size\":\"a4\",\"orientation\":\"portrait\",\"page_width\":210,\"page_height\":297,\"margin\":18,\"font_size\":12,\"line_spacing\":2,\"words\":0,\"lines\":0},\"pagination\":{\"show_page_numbers\":1,\"no_number_on_first\":0,\"page_number_pos\":\"footer\",\"page_number_format\":\"123\",\"page_number_template\":\"{author} • {title} • стр. {page}/{total}\",\"line_numbers_mode\":\"none\",\"line_numbers_placement\":\"\"},\"sections\":{\"new_page_on_header\":0,\"header_page_break_levels\":[],\"new_page_on_file\":1,\"file_name_as_section\":1,\"wrap_lines\":\"yes\"}},\"meta\":{\"title\":\"\",\"author\":\"\",\"course\":\"\",\"citation_template\